                "const": false
              },
              {
                "const": "*"
              },
              {
                "type": "array",
                "minItems": 1,
                "maxItems": 32,
                "items": {
                  "type": "string",
                  "pattern": "^(\\*\\.)?[a-z0-9.-]{1,253}$"
                }
              }
            ],
            "description": "false, \"*\" or hosts like api.example.com and *.example.com"
          },
          "control": {
            "type": "boolean",
            "description": "Let programs you run drive your tabs and pages"
          }
        },
        "additionalProperties": false
      },
      "contributes": {
        "type": "object",
        "properties": {
          "commands": {
            "type": "array",
            "maxItems": 20,
            "items": {
              "type": "object",
              "properties": {
                "name": {
